use std::{fs,path::Path,collections::BTreeMap,io::Read};
use sha2::{Digest,Sha256};
fn hash(p:&Path)->String {let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn walk(p:&Path,root:&Path,out:&mut BTreeMap<String,String>){for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){walk(&p,root,out)}else if p.file_name().unwrap()!="SHA256SUMS"{out.insert(p.strip_prefix(root).unwrap().display().to_string(),hash(&p));}}}
